import { useEffect, useState } from "react";
import ImageList from "@mui/material/ImageList";
import IconButton from "@mui/material/IconButton";
import FavoriteIcon from "@mui/icons-material/Favorite";
import InfoIcon from "@mui/icons-material/Info";
import SelectOrder from "../components/selectOrder";
import { useDispatch, useSelector } from "react-redux";
import { deletePhoto } from "../features/favorites/favoritesSlice";
import { selectFavorites } from "../features/favorites/favoritesSlice";
import TransitionsModal from "../components/modal";
import PhotoCard from "../components/PhotoCard";
import {
  Box,
  Button,
  OutlinedInput,
  InputAdornment,
  Pagination,
  Typography,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import { useNavigate } from "react-router-dom";
import { TopBar } from "../components/TopBar";
import useMediaQuery from "@mui/material/useMediaQuery";

const photosPerPage = 12;

export function Liked() {
  const [open, setOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [orderBy, setOrderBy] = useState("");
  const [myPhotos, setMyPhotos] = useState([]);
  const [data, setData] = useState({
    description: "",
    id: "",
    width: "",
    height: "",
    likes: "",
    dateImported: 0,
    urls: {},
  });
  const [currentPage, setCurrentPage] = useState(1);

  const photosFavs = useSelector(selectFavorites);
  const dispatch = useDispatch();

  const handleClose = () => setOpen(false);
  const handleDelete = (photo) => {
    dispatch(deletePhoto(photo));
  };
  const handleOpen = (item) => {
    setOpen(true);
    setData(item);
  };
  const handleFavsChange = (e, value) => {
    setCurrentPage(value);
  };

  useEffect(() => {
    let filteredPhotos;
    if (searchTerm.length) {
      filteredPhotos = photosFavs.filter(
        (p) =>
          p.description &&
          p.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
    } else {
      filteredPhotos = photosFavs;
    }

    const orderedPhotos = [...filteredPhotos];
    switch (orderBy) {
      case "width":
        orderedPhotos.sort((a, b) => a.width - b.width);
        break;
      case "height":
        orderedPhotos.sort((a, b) => a.height - b.height);
        break;
      case "likes":
        orderedPhotos.sort((a, b) => b.likes - a.likes);
        break;
      case "date":
        orderedPhotos.sort((a, b) => b.dateImported - a.dateImported);
        break;
      default:
        break;
    }
    setMyPhotos(orderedPhotos);
  }, [searchTerm, orderBy, photosFavs]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, orderBy]);

  const numPages = Math.ceil(myPhotos.length / photosPerPage);

  useEffect(() => {
    if (currentPage > numPages && numPages > 0) {
      setCurrentPage(numPages);
    }
  }, [numPages, currentPage]);

  const navigate = useNavigate();
  const handleClick = () => {
    navigate("/search");
  };

  const large = useMediaQuery("(min-width: 1000px)");
  const medium = useMediaQuery("(min-width: 600px)");

  let cols = 1;
  if (large) {
    cols = 4;
  } else if (medium) {
    cols = 2;
  }

  return (
    <div className="page">
      <TopBar />
      <div className="page-container">
        <Box
          display="flex"
          justifyContent="flex-end"
          alignItems="center"
          gap={2}
          flexWrap="wrap"
          mb={4}
        >
          <OutlinedInput
            placeholder="Search by description..."
            startAdornment={
              <InputAdornment position="start">
                <SearchIcon color="disabled" />
              </InputAdornment>
            }
            onChange={(e) => setSearchTerm(e.target.value)}
            size="small"
            sx={{ minWidth: 240, bgcolor: "background.paper" }}
          />
          <SelectOrder orderBy={orderBy} setOrderBy={setOrderBy} />
        </Box>

        {myPhotos.length === 0 ? (
          <Box textAlign="center" py={10}>
            <Typography variant="h5" color="text.primary" mb={1}>
              No favorite photos yet
            </Typography>
            <Typography color="text.secondary" mb={4}>
              Save the images you love and they'll show up here.
            </Typography>
            <Button variant="contained" onClick={handleClick}>
              Go to search page
            </Button>
          </Box>
        ) : (
          <ImageList variant="masonry" cols={cols} gap={18}>
            {myPhotos
              .slice(
                (currentPage - 1) * photosPerPage,
                currentPage * photosPerPage
              )
              .map((item) => (
                <PhotoCard
                  key={item.id}
                  item={item}
                  actions={
                    <>
                      <IconButton
                        size="small"
                        aria-label="view details"
                        onClick={() => handleOpen(item)}
                      >
                        <InfoIcon />
                      </IconButton>
                      <IconButton
                        size="small"
                        aria-label="remove favorite"
                        onClick={() => handleDelete(item)}
                      >
                        <FavoriteIcon sx={{ color: "#ff4d6d" }} />
                      </IconButton>
                    </>
                  }
                />
              ))}
          </ImageList>
        )}

        {numPages > 1 && (
          <Box display="flex" justifyContent="center" mt={4}>
            <Pagination
              count={numPages}
              page={currentPage}
              onChange={handleFavsChange}
              color="primary"
            />
          </Box>
        )}

        <TransitionsModal open={open} handleClose={handleClose} data={data} />
      </div>
    </div>
  );
}
