import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";

const baseUrl = "https://api.unsplash.com/";
const apiKey = process.env.REACT_APP_UNSPLASH_ACCESS_KEY;
const photosPerPage = 28;

export const fetchPhotos = createAsyncThunk(
  "photos/fetchPhotos",
  async ({ query, currentPage }) => {
    const params = new URLSearchParams({
      client_id: apiKey,
      per_page: String(photosPerPage),
    });

    let url;
    if (query && query.length) {
      params.set("query", query);
      params.set("page", String(currentPage));
      url = `${baseUrl}search/photos?${params.toString()}`;
    } else {
      params.set("count", String(photosPerPage));
      url = `${baseUrl}photos/random?${params.toString()}`;
    }

    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Unsplash request failed with status ${response.status}`);
    }

    const json = await response.json();

    if (query && query.length) {
      const total = Number(response.headers.get("X-Total"));
      const totalPages = total ? Math.ceil(total / photosPerPage) : 1;
      return { results: json.results ?? [], totalPages };
    }

    return { results: json ?? [], totalPages: 1 };
  }
);

const searchSlice = createSlice({
  name: "photos",
  initialState: {
    results: [],
    isLoading: false,
    hasError: false,
    totalPages: 1,
  },
  reducers: {},
  extraReducers(builder) {
    builder
      .addCase(fetchPhotos.pending, (state) => {
        state.isLoading = true;
        state.hasError = false;
      })
      .addCase(fetchPhotos.fulfilled, (state, action) => {
        state.isLoading = false;
        state.hasError = false;
        state.results = action.payload.results;
        state.totalPages = action.payload.totalPages;
      })
      .addCase(fetchPhotos.rejected, (state) => {
        state.isLoading = false;
        state.hasError = true;
      });
  },
});

export default searchSlice.reducer;
export const selectPhotos = (state) => state.photos.results;
export const selectTotalPages = (state) => state.photos.totalPages;
export const selectIsLoading = (state) => state.photos.isLoading;
export const selectHasError = (state) => state.photos.hasError;
