import { useState, useEffect } from "react";
import ImageList from "@mui/material/ImageList";
import {
  fetchPhotos,
  selectPhotos,
  selectTotalPages,
  selectIsLoading,
  selectHasError,
} from "../features/search/searchSlice";
import { useDispatch, useSelector } from "react-redux";
import {
  addPhoto,
  deletePhoto,
  selectFavorites,
} from "../features/favorites/favoritesSlice";
import PhotoCard from "../components/PhotoCard";
import {
  Box,
  IconButton,
  OutlinedInput,
  InputAdornment,
  Pagination,
  Typography,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import FavoriteIcon from "@mui/icons-material/Favorite";
import FavoriteBorderIcon from "@mui/icons-material/FavoriteBorder";
import { ClipLoader } from "react-spinners";
import { TopBar } from "../components/TopBar";
import useMediaQuery from "@mui/material/useMediaQuery";

export function Search() {
  const [query, setQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const dispatch = useDispatch();
  const photosRes = useSelector(selectPhotos);
  const totalPages = useSelector(selectTotalPages);
  const isLoading = useSelector(selectIsLoading);
  const hasError = useSelector(selectHasError);
  const favorites = useSelector(selectFavorites);

  const handlePageChange = (e, value) => {
    setCurrentPage(value);
    dispatch(fetchPhotos({ query, currentPage: value }));
  };

  const handleSearch = (e) => {
    setCurrentPage(1);
    setQuery(e.target.value);
  };

  useEffect(() => {
    dispatch(fetchPhotos({ query, currentPage: 1 }));
  }, [query, dispatch]);

  const large = useMediaQuery("(min-width: 1000px)");
  const medium = useMediaQuery("(min-width: 600px)");

  let cols = 1;
  if (large) {
    cols = 4;
  } else if (medium) {
    cols = 2;
  }

  return (
    <div className="page">
      <TopBar />
      <div className="page-container">
        <Box display="flex" justifyContent="center" mb={4}>
          <OutlinedInput
            placeholder="Search for photos..."
            startAdornment={
              <InputAdornment position="start">
                <SearchIcon color="disabled" />
              </InputAdornment>
            }
            onChange={handleSearch}
            fullWidth
            sx={{ maxWidth: 560, bgcolor: "background.paper" }}
          />
        </Box>

        {isLoading && (
          <Box display="flex" justifyContent="center" my={8}>
            <ClipLoader color="#256D85" size={44} />
          </Box>
        )}

        {hasError && (
          <Typography variant="h6" color="text.secondary" textAlign="center" my={8}>
            Something went wrong loading the images. Please try again later.
          </Typography>
        )}

        {!isLoading && !hasError && (
          <ImageList variant="masonry" cols={cols} gap={18}>
            {photosRes.map((item) => {
              const isFavorite = favorites.some((p) => p.id === item.id);
              return (
                <PhotoCard
                  key={item.id}
                  item={item}
                  actions={
                    <IconButton
                      size="small"
                      aria-label="toggle favorite"
                      onClick={() =>
                        isFavorite
                          ? dispatch(deletePhoto({ id: item.id }))
                          : dispatch(addPhoto(item))
                      }
                    >
                      {isFavorite ? (
                        <FavoriteIcon sx={{ color: "#ff4d6d" }} />
                      ) : (
                        <FavoriteBorderIcon />
                      )}
                    </IconButton>
                  }
                />
              );
            })}
          </ImageList>
        )}

        {!isLoading && !hasError && (
          <Box display="flex" justifyContent="center" mt={4}>
            <Pagination
              count={totalPages}
              page={currentPage}
              onChange={handlePageChange}
              color="primary"
            />
          </Box>
        )}
      </div>
    </div>
  );
}
