import { useEffect, useState } from "react";
import Box from "@mui/material/Box";
import Modal from "@mui/material/Modal";
import Fade from "@mui/material/Fade";
import Typography from "@mui/material/Typography";
import { Button, TextareaAutosize } from "@mui/material";
import { useDispatch } from "react-redux";
import { editPhoto } from "../features/favorites/favoritesSlice";

const style = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  width: { xs: "90%", sm: 420 },
  bgcolor: "background.paper",
  borderRadius: 3,
  boxShadow: 24,
  p: 4,
  outline: "none",
};

export default function ChildrenModal(props) {
  const [descriptionPhoto, setDescriptionPhoto] = useState("");
  const dispatch = useDispatch();

  const handleClickSaveDescription = () => {
    dispatch(editPhoto({ id: props.data.id, descriptionPhoto }));
    props.handleClose2();
    props.handleClose1();
  };

  useEffect(() => {
    setDescriptionPhoto(props.data.description ?? "");
  }, [props.data]);

  return (
    <div>
      <Modal
        aria-labelledby="transition-modal-title"
        aria-describedby="transition-modal-description"
        open={props.open2}
        onClose={props.handleClose2}
        closeAfterTransition
      >
        <Fade in={props.open2}>
          <Box sx={style}>
            <Typography id="transition-modal-title" variant="h6" component="h2">
              Edit description
            </Typography>
            <Box mt={2}>
              <TextareaAutosize
                aria-label="minimum height"
                minRows={7}
                style={{
                  width: "100%",
                  padding: 12,
                  borderRadius: 12,
                  border: "1px solid #e4e9f0",
                  fontFamily: "inherit",
                  fontSize: "0.95rem",
                }}
                value={descriptionPhoto}
                onChange={(e) => setDescriptionPhoto(e.target.value)}
              />
              <Button
                variant="contained"
                sx={{ mt: 2 }}
                onClick={handleClickSaveDescription}
              >
                Save
              </Button>
            </Box>
          </Box>
        </Fade>
      </Modal>
    </div>
  );
}
