import ImageListItem from "@mui/material/ImageListItem";

export default function PhotoCard({ item, actions }) {
  return (
    <ImageListItem className="photo-list-item">
      <div className="photo-card">
        <img
          src={item.urls.small || item.urls.thumb}
          alt={item.alt_description || ""}
          loading="lazy"
        />
        <div className="photo-card-bar">
          <span className="photo-card-title">
            {!item.description ? "Untitled" : item.description}
          </span>
          <div className="photo-card-actions">{actions}</div>
        </div>
      </div>
    </ImageListItem>
  );
}
